    side: str            # UP / DOWN
    action: str          # BUY / SELL
    price: float
    shares: float        # заявленные/исполненные шейры до комиссии
    net_shares: float    # сколько реально пришло/ушло шейров
    cash: float          # сколько денег ушло (+) или пришло (-)
    fee_usd: float
    liquidity: str       # maker / taker


@dataclass
class Position:
    qty: dict = field(default_factory=lambda: {UP: 0.0, DOWN: 0.0})
    spent: float = 0.0
    fees: float = 0.0
    bought_shares: dict = field(default_factory=lambda: {UP: 0.0, DOWN: 0.0})
    bought_cost: dict = field(default_factory=lambda: {UP: 0.0, DOWN: 0.0})
    fills: list = field(default_factory=list)

    # ---------- применение исполнений ----------
    def apply(self, fill: Fill) -> None:
        if fill.action == "BUY":
            self.qty[fill.side] += fill.net_shares
            self.bought_shares[fill.side] += fill.net_shares
            self.bought_cost[fill.side] += fill.cash
        else:
            self.qty[fill.side] -= fill.net_shares
        self.spent += fill.cash
        self.fees += fill.fee_usd
        self.fills.append(fill)

    def buy_maker(self, side: str, shares: float, price: float) -> Fill:
        f = Fill(side, "BUY", price, shares, shares, shares * price, 0.0, "maker")
        self.apply(f)
        return f

    def buy_taker(self, side: str, shares: float, price: float, rate: float,
                  exponent: float = 1.0, fee_in_shares: bool = True) -> Fill:
        net, cost, fu = taker_buy_net_shares(shares, price, rate, exponent, fee_in_shares)
        f = Fill(side, "BUY", price, shares, net, cost, fu, "taker")
        self.apply(f)
        return f

    def sell_taker(self, side: str, shares: float, price: float, rate: float,
                   exponent: float = 1.0) -> Fill:
        fu = fee_usd(shares, price, rate, exponent)
        f = Fill(side, "SELL", price, shares, shares, -(shares * price - fu), fu, "taker")
        self.apply(f)
        return f

    # ---------- метрики ----------
    def pnl_if(self, side: str) -> float:
        return self.qty[side] - self.spent

    @property
    def pnl_if_up(self) -> float:
        return self.pnl_if(UP)

    @property
    def pnl_if_down(self) -> float:
        return self.pnl_if(DOWN)

    @property
    def worst_case(self) -> float:
        return min(self.pnl_if_up, self.pnl_if_down)

    @property
    def is_empty(self) -> bool:
        return self.qty[UP] < EPS and self.qty[DOWN] < EPS and abs(self.spent) < EPS

    def unhedged_risk(self) -> float:
        """Сколько долларов теряем в худшем исходе (0, если худший исход не в минус)."""
        return max(0.0, -self.worst_case)

    def is_hedged(self, min_profit: MinProfit) -> bool:
        if self.is_empty:
            return False
        return self.worst_case >= min_profit.required(self.spent) - EPS

    def avg_price(self, side: str) -> float | None:
        s = self.bought_shares[side]
        return self.bought_cost[side] / s if s > EPS else None

    def leading_side(self) -> str | None:
        if abs(self.qty[UP] - self.qty[DOWN]) < EPS:
            return None
        return UP if self.qty[UP] > self.qty[DOWN] else DOWN

    def deficit(self, side: str) -> float:
        """На сколько шейров side отстаёт от другой ноги (0, если не отстаёт)."""
        return max(0.0, self.qty[other(side)] - self.qty[side])

    def clone(self) -> "Position":
        c = copy.copy(self)
        c.qty = dict(self.qty)
        c.bought_shares = dict(self.bought_shares)
        c.bought_cost = dict(self.bought_cost)
        c.fills = list(self.fills)
        return c

    # ---------- "что если" ----------
    def what_if_maker_buy(self, side: str, shares: float, price: float) -> "Position":
        c = self.clone()
        c.buy_maker(side, shares, price)
        return c

    def max_hedge_price_maker(self, side: str, shares: float, min_profit: MinProfit,
                              tick: float = 0.01) -> float | None:
        """Максимальная цена мейкер-покупки `shares` шейров стороны `side`, при которой
        после покупки worst_case >= MIN_PROFIT. Округлено вниз к тику. None - такой цены нет.

        Аналитически: после покупки n по p (без комиссии)
          pnl_side  = qty_side + n - S - n p
          pnl_other = qty_other    - S - n p
        Оба >= req(S + n p). req линейна по p, значит ищем максимум p из двух неравенств.
        """
        if shares <= EPS:
            return None
        S = self.spent
        n = shares
        best = None
        for base in (self.qty[side] + n, self.qty[other(side)]):
            # base - S - n p >= req(S + n p)
            if min_profit.pct is not None:
                k = min_profit.pct
                # base - S - n p >= k S + k n p  ->  p <= (base - S(1+k)) / (n (1+k))
                p = (base - S * (1 + k)) / (n * (1 + k))
            else:
                p = (base - S - (min_profit.usd or 0.0)) / n
            best = p if best is None else min(best, p)
        if best is None:
            return None
        best = min(best, 1.0 - tick)
        p = floor_to_tick(best, tick)
        if p < tick - EPS:
            return None
        return p


def walk_book(levels: list[tuple[float, float]], shares: float,
              limit_price: float | None = None, is_buy: bool = True) -> list[tuple[float, float]]:
    """Проход по стакану. levels - уже отсортированы от лучшей цены.
    Возвращает список (цена, шейры) исполнений; может быть неполным (FAK)."""
    out = []
    left = shares
    for price, size in levels:
        if left <= EPS:
            break
        if limit_price is not None:
            if is_buy and price > limit_price + EPS:
                break
            if not is_buy and price < limit_price - EPS:
                break
        take = min(left, size)
        if take > EPS:
            out.append((price, take))
            left -= take
    return out

