  подписка {"assets_ids": [...], "type": "market", "custom_feature_enabled": true},
  heartbeat: текстовый "PING" каждые 10 с (сервер отвечает "PONG"),
  события: book, price_change, last_trade_price, tick_size_change, best_bid_ask, market_resolved.
  Динамическая подписка: {"assets_ids": [...], "operation": "subscribe"|"unsubscribe"}.

PriceFeed - цена BTC:
  основной источник: RTDS wss://ws-live-data.polymarket.com, топик crypto_prices_chainlink btc/usd
    (публичный, но помечен в доках как устаревший - заменён PolyBolt, который требует API-ключи);
  резерв: Binance btcusdt@trade (только для защиты от резких движений, если RTDS замолчал).
"""
from __future__ import annotations

import asyncio
import json
import logging
import random
import time
from collections import deque
from dataclasses import dataclass, field
from typing import Callable

import websockets

log = logging.getLogger("feeds")


@dataclass
class Book:
    bids: dict = field(default_factory=dict)   # price -> size
    asks: dict = field(default_factory=dict)
    best_bid: float | None = None
    best_ask: float | None = None
    last_trade: float | None = None
    updated: float = 0.0                        # time.monotonic() последнего обновления

    def sorted_asks(self) -> list[tuple[float, float]]:
        return sorted(((p, s) for p, s in self.asks.items() if s > 0), key=lambda x: x[0])

    def sorted_bids(self) -> list[tuple[float, float]]:
        return sorted(((p, s) for p, s in self.bids.items() if s > 0), key=lambda x: -x[0])

    def recompute_top(self):
        a = [p for p, s in self.asks.items() if s > 0]
        b = [p for p, s in self.bids.items() if s > 0]
        self.best_ask = min(a) if a else None
        self.best_bid = max(b) if b else None


Listener = Callable[[str, str, dict], None]   # (event_type, asset_id, raw_msg)


class MarketFeed:
    def __init__(self, url: str):
        self.url = url
        self.assets: set[str] = set()
        self.books: dict[str, Book] = {}
        self.listeners: list[Listener] = []
        self.connected = False
        self.disconnects = 0
        self._ws = None
        self._stop = False

    # ---------- API ----------
    def add_listener(self, fn: Listener):
        self.listeners.append(fn)

    def book(self, asset: str) -> Book:
        return self.books.setdefault(asset, Book())

    def book_age(self, asset: str) -> float:
        b = self.books.get(asset)
        if not b or not b.updated:
            return float("inf")
        return time.monotonic() - b.updated

    async def subscribe(self, assets: list[str]):
        new = [a for a in assets if a not in self.assets]
        self.assets.update(assets)
        for a in assets:
            self.books.setdefault(a, Book())
        if new and self._ws is not None and self.connected:
            try:
                await self._ws.send(json.dumps({"assets_ids": new, "operation": "subscribe",
                                                "custom_feature_enabled": True}))
            except Exception as e:  # noqa: BLE001
                log.warning("subscribe send failed: %r", e)

    async def unsubscribe(self, assets: list[str]):
        gone = [a for a in assets if a in self.assets]
        for a in gone:
            self.assets.discard(a)
            self.books.pop(a, None)
        if gone and self._ws is not None and self.connected:
            try:
                await self._ws.send(json.dumps({"assets_ids": gone, "operation": "unsubscribe"}))
            except Exception as e:  # noqa: BLE001
                log.warning("unsubscribe send failed: %r", e)

    def stop(self):
        self._stop = True

    # ---------- цикл с реконнектом ----------
    async def run(self):
        backoff = 1.0
        while not self._stop:
            if not self.assets:
                await asyncio.sleep(0.5)
                continue
            try:
                async with websockets.connect(self.url, open_timeout=10, ping_interval=None,
                                              max_size=2**23) as ws:
                    self._ws = ws
                    await ws.send(json.dumps({"assets_ids": sorted(self.assets), "type": "market",
                                              "custom_feature_enabled": True}))
                    self.connected = True
                    log.info("CLOB WS connected, %d assets", len(self.assets))
                    backoff = 1.0
                    pinger = asyncio.create_task(self._ping(ws))
                    try:
                        async for raw in ws:
                            if raw == "PONG":
                                continue
                            self._handle(raw)
                    finally:
                        pinger.cancel()
            except asyncio.CancelledError:
                raise
            except Exception as e:  # noqa: BLE001
                log.warning("CLOB WS error: %r", e)
            self.connected = False
            self._ws = None
            self.disconnects += 1
            for b in self.books.values():   # старый стакан больше не валиден
                b.updated = 0.0
            if self._stop:
                break
            wait = backoff + random.uniform(0, backoff / 2)
            log.warning("CLOB WS disconnected, reconnect in %.1fs", wait)
            await asyncio.sleep(wait)
            backoff = min(backoff * 2, 30)

    async def _ping(self, ws):
        while True:
            await asyncio.sleep(10)
            await ws.send("PING")

    # ---------- разбор сообщений ----------
    def _handle(self, raw: str):
        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            return
        items = data if isinstance(data, list) else [data]
        for msg in items:
            et = msg.get("event_type")
            try:
                self._apply(et, msg)
            except Exception as e:  # noqa: BLE001
                log.exception("bad %s message: %r", et, e)

    def _emit(self, et: str, asset: str, msg: dict):
        for fn in self.listeners:
            try:
                fn(et, asset, msg)
            except Exception:  # noqa: BLE001
                log.exception("listener failed on %s", et)

    def _apply(self, et: str, msg: dict):
        now = time.monotonic()
        if et == "book":
            a = msg["asset_id"]
            if a not in self.assets:
                return
            b = self.book(a)
            b.bids = {float(l["price"]): float(l["size"]) for l in msg.get("bids", [])}
            b.asks = {float(l["price"]): float(l["size"]) for l in msg.get("asks", [])}
            b.recompute_top()
            b.updated = now
            self._emit(et, a, msg)
        elif et == "price_change":
            touched = set()
            for ch in msg.get("price_changes", []):
                a = ch["asset_id"]
                if a not in self.assets:
                    continue
                b = self.book(a)
                side = b.bids if ch["side"] == "BUY" else b.asks
                p, s = float(ch["price"]), float(ch["size"])
                if s <= 0:
                    side.pop(p, None)
                else:
                    side[p] = s
                if ch.get("best_bid") is not None and ch.get("best_ask") is not None:
                    b.best_bid = float(ch["best_bid"]) or None
                    b.best_ask = float(ch["best_ask"]) or None
                else:
                    b.recompute_top()
                b.updated = now
                touched.add(a)
            for a in touched:
                self._emit(et, a, msg)
        elif et == "best_bid_ask":
            a = msg["asset_id"]
            if a not in self.assets:
                return
            b = self.book(a)
            b.best_bid = float(msg["best_bid"]) if msg.get("best_bid") else None
            b.best_ask = float(msg["best_ask"]) if msg.get("best_ask") else None
            b.updated = now
            self._emit(et, a, msg)
        elif et == "last_trade_price":
            a = msg["asset_id"]
            if a not in self.assets:
                return
            b = self.book(a)
            b.last_trade = float(msg["price"])
            b.updated = now
            self._emit(et, a, msg)
        elif et == "tick_size_change":
            self._emit(et, msg.get("asset_id", ""), msg)
        elif et == "market_resolved":
            self._emit(et, msg.get("winning_asset_id", ""), msg)


class PriceFeed:
    """Цена BTC/USD: Chainlink через RTDS + резервный Binance."""

    def __init__(self, rtds_url: str, binance_url: str | None, stale_sec: float = 10):
        self.rtds_url = rtds_url
        self.binance_url = binance_url
        self.stale_sec = stale_sec
        self.hist: dict[str, deque] = {"chainlink": deque(maxlen=600), "binance": deque(maxlen=600)}
        self.last_recv: dict[str, float] = {"chainlink": 0.0, "binance": 0.0}
        self._stop = False

    def stop(self):
        self._stop = True

    def _push(self, src: str, value: float):
        now = time.monotonic()
        h = self.hist[src]
        if src == "binance" and h and now - h[-1][0] < 0.5:   # прореживаем поток сделок
            h[-1] = (h[-1][0], value)
        else:
            h.append((now, value))
        self.last_recv[src] = now

    def fresh(self, src: str) -> bool:
        return time.monotonic() - self.last_recv[src] < self.stale_sec

    def source(self) -> str | None:
        if self.fresh("chainlink"):
            return "chainlink"
        if self.fresh("binance"):
            return "binance"
        return None

    def price(self) -> tuple[float | None, str | None]:
        src = self.source()
        if not src:
            return None, None
        return self.hist[src][-1][1], src

    def move_bps(self, sec: float) -> tuple[float | None, str | None]:
        """Изменение цены за последние sec секунд в б.п. (+ вверх, - вниз)."""
        src = self.source()
        if not src:
            return None, None
        h = self.hist[src]
        now_t, now_p = h[-1]
        ref = None
        for t, p in reversed(h):
            ref = p
            if now_t - t >= sec:
                break
        if not ref:
            return None, src
        return (now_p - ref) / ref * 1e4, src

    async def run(self):
        tasks = [asyncio.create_task(self._rtds())]
        if self.binance_url:
            tasks.append(asyncio.create_task(self._binance()))
        await asyncio.gather(*tasks)

    async def _rtds(self):
        backoff = 1.0
        sub = {"action": "subscribe", "subscriptions": [
            {"topic": "crypto_prices_chainlink", "type": "*", "filters": "{\"symbol\":\"btc/usd\"}"}]}
        while not self._stop:
            try:
                async with websockets.connect(self.rtds_url, open_timeout=10, ping_interval=None) as ws:
                    await ws.send(json.dumps(sub))
                    log.info("RTDS connected (Chainlink BTC/USD)")
                    backoff = 1.0
                    pinger = asyncio.create_task(self._ping(ws, 5))
                    try:
                        async for raw in ws:
                            if not raw or raw == "PONG":
                                continue
                            try:
                                msg = json.loads(raw)
                            except json.JSONDecodeError:
                                continue
                            pl = msg.get("payload") or {}
                            if pl.get("symbol") == "btc/usd" and pl.get("value"):
                                self._push("chainlink", float(pl["value"]))
                            elif isinstance(pl.get("data"), list) and pl["data"]:
                                self._push("chainlink", float(pl["data"][-1]["value"]))
                    finally:
                        pinger.cancel()
            except asyncio.CancelledError:
                raise
            except Exception as e:  # noqa: BLE001
                log.warning("RTDS error: %r", e)
            if self._stop:
                break
            wait = backoff + random.uniform(0, backoff / 2)
            log.warning("RTDS disconnected, reconnect in %.1fs", wait)
            await asyncio.sleep(wait)
            backoff = min(backoff * 2, 30)

    async def _binance(self):
        backoff = 1.0
        while not self._stop:
            try:
                async with websockets.connect(self.binance_url, open_timeout=10) as ws:
                    log.info("Binance fallback connected")
                    backoff = 1.0
                    async for raw in ws:
                        try:
                            self._push("binance", float(json.loads(raw)["p"]))
                        except (KeyError, ValueError, json.JSONDecodeError):
                            pass
            except asyncio.CancelledError:
                raise
            except Exception as e:  # noqa: BLE001
                log.warning("Binance error: %r", e)
            if self._stop:
                break
            await asyncio.sleep(backoff + random.uniform(0, backoff / 2))
            backoff = min(backoff * 2, 60)

    @staticmethod
    async def _ping(ws, every: float):
        while True:
            await asyncio.sleep(every)
            await ws.send("PING")

