"""Риск: kill-switch, дневной стоп (UTC), режимы торговли.

mode():
  "stopped"    - kill-switch /stop: все ордера сняты, ничего не котируем (FORCE тоже не делаем)
  "hedge_only" - дневной стоп: новых входов нет, но недостающую ногу добираем, чтобы не сидеть в риске
  "ok"         - обычная торговля
"""
from __future__ import annotations

import logging

from storage import Storage, utc_day

log = logging.getLogger("risk")


class Risk:
    def __init__(self, cfg, storage: Storage):
        self.cfg = cfg
        self.storage = storage
        self._last_mode = None

    @property
    def killed(self) -> bool:
        return self.storage.get("kill", "0") == "1"

    def kill(self, on: bool):
        self.storage.set("kill", "1" if on else "0")
        log.warning("KILL-SWITCH %s", "ON" if on else "OFF")

    def day_pnl(self) -> float:
        return self.storage.day_pnl(utc_day())

    def day_risk(self) -> float:
        """Реализованный PnL дня + худший исход по незакрытым окнам."""
        return self.day_pnl() + self.storage.pending_worst()

    def daily_stopped(self) -> bool:
        return self.day_risk() <= -self.cfg.daily_max_loss_usd

    def mode(self) -> str:
        if self.killed:
            m = "stopped"
        elif self.daily_stopped():
            m = "hedge_only"
        else:
            m = "ok"
        if m != self._last_mode:
            log.warning("risk mode -> %s (day pnl %.2f, day risk %.2f)", m, self.day_pnl(), self.day_risk())
            self._last_mode = m
        return m

