"""Пишет сырые события фидов (стакан CLOB + цена Chainlink/Binance) по каждому окну
в records/<slug>.jsonl. Не влияет на торговлю - чисто для последующего офлайн-реплея
(backtest.py), чтобы честно сравнивать варианты стратегии на одних и тех же исторических
данных, а не на разных случайных минутах живого рынка.

Формат файла (по одной JSON-записи на строку):
  {"type":"header", "slug":..., "start_ts":..., "end_ts":..., "token":{"UP":...,"DOWN":...},
   "tick":..., "min_size":..., "fee_rate":..., "fee_exponent":..., "question":...}
  {"type":"clob", "et":"book"/"price_change"/..., "asset":"...", "t": <сек от начала окна>, "msg": {...}}
  {"type":"price", "src":"chainlink"/"binance", "t": <сек от начала окна>, "value": ...}
  {"type":"resolution", "winner": "UP"/"DOWN"/null}     <- последняя строка
"""
from __future__ import annotations

import json
import logging
import os
import time

log = logging.getLogger("recorder")


class Recorder:
    def __init__(self, out_dir: str):
        self.dir = out_dir
        self.files: dict[str, dict] = {}       # slug -> {"f": handle, "start_ts": float}
        self.token_slug: dict[str, str] = {}   # token_id -> slug

    def begin(self, market):
        os.makedirs(self.dir, exist_ok=True)
        path = os.path.join(self.dir, f"{market.slug}.jsonl")
        f = open(path, "w", encoding="utf-8")
        header = {"type": "header", "slug": market.slug, "start_ts": market.start_ts, "end_ts": market.end_ts,
                  "token": market.token, "tick": market.tick, "min_size": market.min_size,
                  "fee_rate": market.fee_rate, "fee_exponent": market.fee_exponent, "question": market.question}
        f.write(json.dumps(header) + "\n")
        self.files[market.slug] = {"f": f, "start_ts": market.start_ts}
        for tok in market.token.values():
            self.token_slug[tok] = market.slug
        log.info("recording -> %s", path)

    def end(self, slug: str, winner: str | None):
        info = self.files.pop(slug, None)
        if not info:
            return
        info["f"].write(json.dumps({"type": "resolution", "winner": winner}) + "\n")
        info["f"].close()
        self.token_slug = {t: s for t, s in self.token_slug.items() if s != slug}
        log.info("recording finished: %s (winner=%s)", slug, winner)

    def on_clob_event(self, et: str, asset: str, msg: dict):
        slug = self.token_slug.get(asset)
        if not slug:
            return
        info = self.files.get(slug)
        if not info:
            return
        rec = {"type": "clob", "et": et, "asset": asset, "t": time.time() - info["start_ts"], "msg": msg}
        try:
            info["f"].write(json.dumps(rec, default=str) + "\n")
        except (TypeError, ValueError):
            pass

    def on_price_event(self, src: str, value: float):
        now = time.time()
        for info in self.files.values():
            rec = {"type": "price", "src": src, "t": now - info["start_ts"], "value": value}
            info["f"].write(json.dumps(rec) + "\n")

    def close_all(self):
        for slug in list(self.files):
            self.end(slug, None)

