        self.risk = Risk(CFG, self.storage)
        self.notifier = Notifier(CFG, self.storage, self.risk)
        self.finder = MarketFinder(CFG.gamma_url)
        self.feed = MarketFeed(CFG.clob_ws_url)
        self.prices = PriceFeed(CFG.rtds_ws_url, CFG.binance_ws_url if CFG.binance_fallback else None,
                                CFG.price_stale_sec)
        self.windows: dict[str, Window] = {}
        self.current: Window | None = None
        self.bg: set[asyncio.Task] = set()
        self.notifier.status_fn = self.status
        self.feed.add_listener(self._route_event)
        if CFG.live_trading:
            self.ex = LiveExecutor(self.storage, CFG)
        else:
            self.ex = PaperExecutor(self.storage, self.feed, CFG.fee_in_shares)

    def _route_event(self, et, asset, msg):
        if et != "market_resolved":
            return
        for w in list(self.windows.values()):
            w.on_market_event(et, asset, msg)

    def status(self) -> str:
        w = self.current
        px, src = self.prices.price()
        head = (f"Режим: {self.ex.mode} | риск: {self.risk.mode()} | PnL дня {self.risk.day_pnl():+.2f}$ | "
                f"BTC {px and round(px, 2)} ({src}) | WS {'ok' if self.feed.connected else 'DOWN'}")
        if not w:
            return head + "\nОкно: нет активного"
        return f"{head}\nОкно {w.m.slug} фаза {w.phase} t={w.elapsed():.0f}s\n{w.pos_str()}"

    def spawn(self, coro):
        t = asyncio.create_task(coro)

    t.add_done_callback(self.bg.discard)
    return t

async def finalize(self, w: Window):
    try:
        if w.pos.is_empty:
            self.storage.update_window(w.m.slug, status=RESOLVED, pnl=0.0, resolved_at=time.time())
            log.info("[%s] no position, window closed with pnl 0", w.tag)
            if CFG.report_empty_windows:
                await self.notifier.send(f"Окно {w.m.slug}: сделок не было.")
        else:
            ok = await w.resolve(self.finder)
            if ok:
                await self.notifier.send(window_report(w, self.risk.day_pnl(), self.ex.mode))
            else:
                await self.notifier.send(f"⚠️ Окно {w.m.slug} не зарезолвилось за {CFG.resolve_timeout_sec}s")
    except Exception:  # noqa: BLE001
        log.exception("finalize failed for %s", w.m.slug)
    finally:
        self.ex.unregister(w.m.slug)
        self.windows.pop(w.m.slug, None)
        if self.current is not w:
            await self.feed.unsubscribe(list(w.m.token.values()))

